INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('1','Terran Human','Human',NULL,'Bipedal mammalian, adaptable to wide range of environments. Standard oxygen breathers with carbon-based biology.','Curious, ambitious, fractious. Form complex social hierarchies but prone to internal conflict. Innovative under pressure.','Adaptable - Can thrive in any habitable environment');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('2','Zarekite','NearHuman','ZAREK','Tall (2.2m avg), slender builds. Pale skin with subtle bioluminescence. Large eyes adapted to bright light. Extended lifespan (200+ years).','Hierarchical, patient, long-term planners. Value knowledge and tradition. Can appear aloof to outsiders.','Light-Adapted - Reduced combat penalties in high-radiation zones');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('3','Lithoid','Xenoform','QUELL','Silicon-based life, crystalline exoskeleton. Slow-moving but incredibly durable. Communicate through subsonic vibrations. No need for atmosphere.','Methodical, territorial, literal-minded. Think in geological timescales. Suspicious of rapid change.','Radiation Immune - No damage from radiation zones');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('4','Kethrani','Xenoform','WEXAR','Aquatic origin, amphibious. Scaled skin, gill slits, webbed digits. Can survive in water or standard atmosphere. Chromatic skin displays emotion.','Gregarious, mercantile, consensus-driven. Natural traders and negotiators. Memory for debts and favors.','Trade Affinity - +1 resource when using trade hubs');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('5','Vesh','Xenoform','TAVON','Insectoid, hive-based. Individual drones are semi-autonomous but linked to hive consciousness. Varied castes for different functions.','Collective, efficient, alien priorities. Communicate through pheromones and gestures. Difficult for individuals to comprehend.','Hive Labor - Facilities produce +50% at Vesh populations');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('6','The Remnant','Machine','VARYN','Artificial constructs of unknown origin. Humanoid frames with crystalline cores. Self-repairing. No biological needs.','Cold logic, inscrutable goals. Claim to serve ancient directives. Cooperative but unpredictable.','Machine Precision - Repair costs reduced by 1 resource');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('7','Wanderers','Human',NULL,'Baseline human stock but culturally distinct. Born and raised on generation ships. Pale, thin from low-gravity environments.','Nomadic, pragmatic, clannish. Distrust of planetary populations. Expert shiphandlers and traders.','Fleet-Born - Ships built at Wanderer facilities get +1 PD');
INSERT INTO system_species (id,name,classification,homeworld_system,physiology,psychology,special_ability) VALUES ('8','The Absent','Elder',NULL,'Unknown. No living specimens. Evidence suggests enormous scale, non-carbon biology, possible dimensional or temporal capabilities.','Unknown. Artifacts suggest vast intellect, incomprehensible motivations. May still exist elsewhere/elsewhen.','Unknown - Artifacts may have unpredictable effects');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('1','ARVEN','Arven Prime','G','Main','Yellow','4.2','Sol-like star. Stable and life-giving. The heart of the Western Alliance.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('2','BELIX','Belix Alpha','K','Main','Orange','6.8','Primary of ancient binary pair. Warm light bathes the inner worlds.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('3','BELIX','Belix Beta','M','Dwarf','Red','6.8','Companion star. Small and distant. Stable L4 colonies orbit between.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('4','CAYRU','Cayru Sol','F','Main','Yellow-White','2.1','Young and energetic. Intense UV output scorches inner planets.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('5','ZAREK','Zarek Ascendant','A','Main','White','0.8','Brilliant young star. Harsh radiation but immense energy output.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('6','ASTREX','Astrex Prima','G','Main','Yellow','5.1','Mature and stable. Extensive habitable zone supports dense populations.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('7','BRION','Brion Dusk','K','Main','Orange','8.2','Ancient star entering late life. Amber light speaks of long history.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('8','DORSAI','Dorsai Flame','K','Main','Orange','5.4','Steady orange glow. First waypoint from Arven.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('9','ELYR','Elyr Wanderer','G','Main','Yellow','3.8','Standard yellow star. Junction between BELIX and HAVOR.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('10','FEXON','Fexon Distant','K','Main','Orange','7.1','Cool orange star at edge of contested space.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('11','GALEN','Galen Shimmer','F','Main','Yellow-White','1.8','Young bright star. Belts form prominent rings visible to naked eye.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('12','HAVOR','Havor Nexus','G','Main','Yellow','4.5','Central star. Three warplines make this a crucial waypoint.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('13','ITHRA','Ithra Ancient','K','Main','Orange','8.9','One of the oldest stars in charted space. Slow and steady.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('14','JEXEL','Jexel Pale','K','Subgiant','Orange','9.2','Slightly expanded. Beginning transition to later stellar phases.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('15','KORAL','Koral Axis','G','Main','Yellow-Orange','3.4','Strategic hub. Four warplines connect here.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('16','LYRIS','Lyris Ember','M','Dwarf','Red','10.2','Dim red dwarf. Cold outer reaches despite proximity to HAVOR.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('17','MAVIK','Mavik Torch','F','Main','Yellow-White','2.3','Bright and hot. Inner planets are scorched wastelands.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('18','NOREX','Norex Beacon','G','Main','Yellow','4.1','Clear and steady. Major crossroads of central space.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('19','OPHIR','Ophir Vigil','K','Main','Orange','6.2','Steady orange star. Close neighbor to Norex.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('20','PRYON','Pryon Fade','M','Dwarf','Red','11.1','Ancient red dwarf. Minimal energy. Harsh living conditions.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('21','QUELL','Quell Vermillion','M','Dwarf','Red','9.1','Ancient stable red dwarf. Source of exotic Keplerite deposits.');
