INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('24','TAVON','Tavon Drone','M','Dwarf','Red','8.4','Dim red light. Homeworld of the Vesh hive collective.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('25','ULEX','Ulex Pale','K','Dwarf','Orange','7.8','Small orange dwarf. Direct route to Zarek.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('26','VARYN','Varyn Eternal','G','Subgiant','Yellow','6.1','Slightly expanded. Home to the mysterious Remnant machines.');
INSERT INTO system_stars (id,system_name,designation,star_class,luminosity,color,age_gy,notes) VALUES ('27','WEXAR','Wexar Jewel','F','Main','Yellow-White','2.8','Bright star with extensive liquid water worlds. Kethrani homeworld.');
