INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('1','BELIX','BEACON_ANCIENT','The Whisper Gate','Unknown. Non-functional but emits faint energy signatures when ships pass between binary stars.','Between Belix Alpha and Beta hangs an ancient structure of impossible geometry. It does not respond to hails but sensors detect energy flows within.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('2','CAYRU','ARTIFACT','Core Fragment','Exotic matter signatures suggest unknown physics. Research ongoing.','Deep within The Shatter lies a crystallized fragment of planetary core. Its composition includes materials not found in any catalog.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('3','ZAREK','ARTIFACT','The First Library','Partially decoded Elder Race data cache. Contains fragments of star charts and incomprehensible records.','Beneath Gilded Throne\'s oldest ruins lies a vault of crystalline data storage. The Zarekites have spent centuries decoding fragments.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('4','ASTREX','SPATIAL_RIFT','Ishtar Gate','Dormant portal structure. Origin unknown. Occasionally fluctuates in energy readings.','On the moon Ishtar stands a ring of unknown metal twenty meters across. It does nothing but ancient texts speak of lights within.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('5','BRION','PHENOMENON','The Dying Light','Unusual spectral emissions from the star. Studied but unexplained. No apparent effect.','Brion Dusk\'s light carries harmonics that should not exist. Spectral analysis reveals patterns that seem almost intentional.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('6','KORAL','BEACON_ANCIENT','Axis Marker','Functional Elder Race navigation beacon. Ships report improved warpline entry efficiency.','At the precise gravitational center of Koral\'s orbital plane floats an ancient beacon still broadcasting after untold millennia.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('7','QUELL','ARTIFACT','The Keplerite Vein','Source of warp-enhancing crystals. Monopolized by Lithoids who extract slowly.','The asteroid belt here contains a massive deposit of crystalline material that resonates with warp field harmonics.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('8','SYDRA','GRAVEYARD','The Scrapyard','Hundreds of destroyed warships from the Last War. Salvage potential but also unexploded ordnance hazard.','The belt is choked with hulks from a battle centuries past. Some still have power. Some still have weapons.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('9','XYLEN','PHENOMENON','The Congregation','Ancient shrine. Pilgrims claim healing properties. No scientific verification.','On Pilgrims End an ancient structure draws the faithful from across space. Some claim miracles. Scientists find nothing unusual.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('10','VARYN','ARTIFACT','The Core','Central processor of the Remnant machine civilization. Source of their directives.','Varyn Eternal orbits a world where machines rule. At its heart lies a crystalline core that even the Remnant claim predates their memory.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('11','TAVON','PHENOMENON','The Song','Vesh hive produces subsonic vibrations felt across the system. Purpose unknown.','The Vesh hive on Tavon emits vibrations that penetrate vacuum. Ships report crew unease. The Vesh claim they are singing.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('12','WEXAR','PHENOMENON','The Deep','Unexplored ocean depths on Wexar I. Kethrani legends speak of something ancient below.','The Kethrani civilization arose on Wexar Jewel from the depths of oceans so deep that even they have not explored the bottom.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('13','GALEN','RADIATION_ZONE','The Shimmer','Intense radiation from close approach to young star creates sensor difficulties in inner system.','Galen Shimmer burns so bright that sensors become unreliable within the inner ring. Ships sometimes see things.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('14','ITHRA','DERELICT','Ancient Station','Pre-colonization orbital structure. Explored but not fully understood.','In high orbit around Ithra II hangs a station that predates human arrival by millennia. The Ithra claim it as heritage.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('15','HAVOR','GRAVEYARD','Junction Debris','Remnants of ancient battles at this strategic junction. Some debris still drifts.','The space around Havor contains fragments of ships from multiple eras. This junction has been fought over many times.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('16','FEXON','DARK_NEBULA','The Veil','Interstellar dust reduces long-range sensors. Ships sometimes arrive unexpectedly.','Dense dust between Fexon and the warplines makes long-range detection difficult. Ambushes are possible here.');
INSERT INTO system_anomalies (id,system_name,anomaly_type,name,effect,discovery_text) VALUES ('17','RAXEN','BEACON_ANCIENT','The Spark','Ancient navigation aid. Less functional than Koral marker but still active.','Just beyond Raxen II an ancient beacon gutters like a failing flame. It may have guided ships here millennia ago.');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ARVEN','The heart of the Western Alliance. A stable yellow star with rich agricultural and industrial worlds.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('BELIX','Ancient binary star system. Population centers on multiple worlds. Strong military presence.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('CAYRU','Young energetic star. The Shatter asteroid belt is said to contain rare metals from a destroyed planet.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ZAREK','Brilliant white star. The Zarekites rule from Gilded Throne where ancient ruins predate their civilization.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ASTREX','Legendary Hanging Gardens orbit Astrex Prima. A center of culture and commerce for the East.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('BRION','Ancient orange star said to be dying slowly. Industrial heartland with depleted resources.','Charted');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('DORSAI','First waypoint from Arven. Mostly undeveloped but strategically positioned.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ELYR','Junction system between Belix and the contested zones. Trade and fishing colonies.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('FEXON','Distant orange star at the edge of charted space. Military outpost guards the approaches.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('GALEN','Young star with spectacular asteroid rings. Rumors of rich mineral deposits.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('HAVOR','Central junction. Three warplines meet here. Heavily trafficked and contested.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ITHRA','One of the oldest stars known. Conservative population guards ancient ways.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('JEXEL','Dim star beginning its expansion. Hardy colonists survive in difficult conditions.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('KORAL','The Axis. Four warplines converge here. Most strategic location in contested space.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('LYRIS','Cold red dwarf near Havor. Sparse population in harsh conditions.','Unknown');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('MAVIK','Bright hot star. Inner planets are furnaces. Industrial development further out.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('NOREX','Major crossroads world. Cosmopolitan population from many cultures.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('OPHIR','Steady orange star near Norex. Border watchers monitor the contested zones.','Unknown');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('PRYON','Dim ancient red dwarf. Survival-focused colonies in minimal conditions.','Unknown');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('QUELL','Isolated red dwarf with single warpline. Rumors of exotic crystalline deposits and alien miners.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('RAXEN','Gateway to eastern territories. Developing colonies with growing importance.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('SYDRA','Four warplines meet at this heavily contested system. War-torn worlds and battle debris.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('TAVON','Home of the Vesh hive collective. Dim red star with dense-atmosphere worlds.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('ULEX','Direct route to Zarek. Strategic gateway to eastern capital.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('VARYN','Home of the Remnant machine civilization. Ancient mysteries abound.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('WEXAR','Kethrani homeworld. Ocean worlds with aquatic culture and extensive trade networks.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('XYLEN','Three-way junction. The Nexus free port welcomes all. Mercenary presence on fortress moons.','Rumored');
INSERT INTO system_grimoire_rumors (system_name,rumor_text,knowledge_level) VALUES ('YORIN','Gateway to Brion. Growing trade center with developing colonies.','Rumored');
